INSERT INTO public.articles (slug, title, excerpt, content, meta_title, meta_description, is_published, author, category) VALUES ('art-1', 'تکنولوژی TLS Fragment چیست و چگونه فیلترینگ DPI را دور می‌زند؟', 'بررسی علمی نحوه شکستن بسته‌های Client Hello در لایه TCP برای جلوگیری از شناسایی SNI توسط تجهیزات فیلترینگ مخابرات.', '<p>در سیستم‌های فیلترینگ پیشرفته مبتنی بر DPI (Deep Packet Inspection)، فایروال محتوای بسته اولیه Handshake را که حاوی نام دامنه (SNI) است بازرسی می‌کند.</p><p>تکنولوژی Fragment این بسته را به قطعات ۱ تا ۳ بایتی ریز تقسیم می‌کند و با تاخیر چند میلی‌ثانیه‌ای می‌فرستد. در نتیجه، فایروال نمی‌تواند پکت را اسمبل کند و اتصال بدون مسدودی برقرار می‌شود.</p><p>پیکربندی بهینه فرگمنت در اپلیکیشن‌های هیدیفای و v2rayNG با تنظیم بازه 10-20 روی پکت 1-3 انجام می‌شود.</p>', 'تکنولوژی TLS Fragment چیست و چگونه فیلترینگ DPI را دور می‌زند؟', 'بررسی علمی نحوه شکستن بسته‌های Client Hello در لایه TCP برای جلوگیری از شناسایی SNI توسط تجهیزات فیلترینگ مخابرات.', true, 'تیم اتصال', 'تکنولوژی و پروتکل') ON CONFLICT DO NOTHING;
INSERT INTO public.articles (slug, title, excerpt, content, meta_title, meta_description, is_published, author, category) VALUES ('art-2', 'مقایسه جامع VLESS Reality با Hysteria 2: کدام برای شما مناسب‌تر است؟', 'تفاوت‌های ساختاری بین اتصال‌های مبتنی بر TCP و UDP و راهنمای انتخاب بهترین پروتکل برای همراه اول، ایرانسل و وای‌فای.', '<p>پروتکل VLESS Reality ترافیک شما را شبیه به یک بازدید وب‌سایت کاملاً عادی از سرورهای مجاز مایکروسافت یا گوگل جلوه می‌دهد.</p><p>در مقابل، پروتکل Hysteria 2 از پروتکل مدرن QUIC مبتنی بر UDP استفاده می‌کند که حتی با پکت‌لاس ۵۰ درصدی سرعت حداکثری دانلود را تأمین می‌کند.</p><p>اگر روی سیم‌کارت همراه اول هستید، Reality بهترین گزینه و اگر روی ایرانسل یا مبین‌نت هستید، هایستریا ۲ سریع‌ترین گزینه است.</p>', 'مقایسه جامع VLESS Reality با Hysteria 2: کدام برای شما مناسب‌تر است؟', 'تفاوت‌های ساختاری بین اتصال‌های مبتنی بر TCP و UDP و راهنمای انتخاب بهترین پروتکل برای همراه اول، ایرانسل و وای‌فای.', true, 'تیم اتصال', 'راهنمای انتخاب') ON CONFLICT DO NOTHING;
INSERT INTO public.articles (slug, title, excerpt, content, meta_title, meta_description, is_published, author, category) VALUES ('art-3', 'تنظیم امن MTProto در تلگرام با استفاده از سکرت‌های جعلی Fake-TLS', 'آموزش شناسایی پروکسی‌های امن تلگرام و جلوگیری از حملات بازپخش (Replay Attacks) در شبکه‌های عمومی.', '<p>پروکسی‌های معمولی متنی به سادگی توسط سامانه‌های سانسور شناسایی و مسدود می‌شوند.</p><p>استفاده از پسوند ee در ابتدای سکرت (Secret) نشان‌دهنده لایه امنیتی Fake TLS است که ترافیک شما را کاملاً شبیه ترافیک وب HTTPS ایمن می‌سازد.</p><p>تمامی پروکسی‌های معرفی‌شده در پورتال اتصال از نوع Fake-TLS با SNI معتبر هستند.</p>', 'تنظیم امن MTProto در تلگرام با استفاده از سکرت‌های جعلی Fake-TLS', 'آموزش شناسایی پروکسی‌های امن تلگرام و جلوگیری از حملات بازپخش (Replay Attacks) در شبکه‌های عمومی.', true, 'تیم اتصال', 'امنیت پیام‌رسان') ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('iran-internet-disruption-datacenter-status-report', 'گزارش آخرین وضعیت اختلالات اینترنت و مسدودسازی پورت‌های امنیتی در دیتاسنترهای داخلی', 'بررسی فنی تغییرات اخیر در سامانه فیلترینگ کشور و اختلالات ایجاد شده روی پروتکل‌های TLS و پورت‌های رمزنگاری شده.', '<p>بر اساس گزارش‌های فنی منتشر شده از سوی مانیتورینگ‌های مستقل و وضعیت اتصال در دیتاسنترهای اصلی کشور (از جمله همراه اول، ایرانسل و های‌وب)، طی روزهای اخیر تغییراتی در سیستم بازرسی عمیق بسته‌ها (DPI) اعمال شده است.</p><p>این تغییرات عمدتاً بر روی شناسایی رفتارهای پروتکل TLS 1.3 و پکت‌های اولیه Handshake متمرکز بوده که باعث بروز کندی و تاخیر در اتصال کاربران عادی به وب‌سایت‌های بین‌المللی شده است.</p><p>توصیه کارشناسان شبکه برای حفظ پایداری ارتباط، استفاده از پروتکل‌های مقاوم در برابر فیلترینگ مانند VLESS Reality با دامنه معتبر (Server Name Indication) و پروتکل Hysteria 2 بر بستر UDP استاندارد است.</p>', 'گزارش آخرین وضعیت اختلالات اینترنت و مسدودسازی پورت‌های امنیتی در دیتاسنترهای داخلی', 'بررسی فنی تغییرات اخیر در سامانه فیلترینگ کشور و اختلالات ایجاد شده روی پروتکل‌های TLS و پورت‌های رمزنگاری شده.', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('cloudflare-radar-global-bgp-routing-security', 'کلادفلر رادار: تحلیل حملات نوین BGP Hijacking و ارتقای امنیت مسیرهای بین‌المللی', 'گزارش شرکت کلادفلر درباره تهدیدات نوظهور در جدول مسیریابی اینترنت جهانی و راهکارهای تایید اعتبار مسیر RPKI.', '<p>سامانه رادار کلادفلر (Cloudflare Radar) در گزارش جدید خود اعلام کرد که خطاهای مسیریابی BGP و حملات جعل مسیر در ۶ ماه گذشته رشد ۱۸ درصدی داشته‌اند.</p><p>این اختلالات می‌توانند ترافیک کاربران را به مقصدهای اشتباه یا سرورهای بازرسی هدایت کنند. پیاده‌سازی امضاهای رمزنگاری RPKI توسط اپراتورهای مخابراتی اصلی‌ترین راه‌حل امن‌سازی هسته اینترنت معرفی شده است.</p>', 'کلادفلر رادار: تحلیل حملات نوین BGP Hijacking و ارتقای امنیت مسیرهای بین‌المللی', 'گزارش شرکت کلادفلر درباره تهدیدات نوظهور در جدول مسیریابی اینترنت جهانی و راهکارهای تایید اعتبار مسیر RPKI.', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('linux-kernel-bbr3-congestion-control-speed-boost', 'توسعه الگوریتم جدید BBRv3 در هسته لینوکس؛ جهش سرعت در شبکه‌های با پکت‌لاس بالا', 'گوگل و جامعه توسعه‌دهندگان لینوکس نسخه سوم الگوریتم کنترل ازدحام BBR را برای بهبود سرعت اتصالات معرفی کردند.', '<p>الگوریتم BBR (Bottleneck Bandwidth and RTT) یکی از بهترین الگوریتم‌های مدیریت ازدحام شبکه در سرورهای لینوکسی است که عملکرد فوق‌العاده‌ای در شبکه‌های با درصد افت بسته (Packet Loss) بالا دارد.</p><p>در نسخه جدید BBRv3، تاخیر صف‌ها تا ۳۰٪ کاهش یافته و پایداری استریم ویدیو و دانلود در شبکه‌های شلوغ تلفن همراه به شکل چشمگیری ارتقا یافته است.</p>', 'توسعه الگوریتم جدید BBRv3 در هسته لینوکس؛ جهش سرعت در شبکه‌های با پکت‌لاس بالا', 'گوگل و جامعه توسعه‌دهندگان لینوکس نسخه سوم الگوریتم کنترل ازدحام BBR را برای بهبود سرعت اتصالات معرفی کردند.', 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('iran-fiber-optic-ftth-coverage-progress-challenges', 'بررسی روند توسعه اینترنت فیبر نوری (FTTH) در شهرهای بزرگ و چالش‌های پهنای باند بین‌الملل', 'ارزیابی وضعیت واقعی پوشش فیبر نوری و کیفیت دسترسی کاربران خانگی به اینترنت با پینگ پایین در سال جاری.', '<p>پروژه توسعه فیبر نوری منازل و کسب‌وکارها در شهرهای مختلف کشور در حال پیگیری است، اما کاربران همچنان با چالش محدودیت در پهنای باند بین‌الملل و نوسان پینگ در ساعات اوج مصرف مواجه هستند.</p><p>کارشناسان معتقدند ارتقای زیرساخت فیزیکی فیبر نوری بدون رفع محدودیت‌های ترانزیت بین‌الملل و اصلاح معماری فیلترینگ، تاثیر محدودی بر کیفیت تجربه وب‌گردی آزاد کاربران خواهد داشت.</p>', 'بررسی روند توسعه اینترنت فیبر نوری (FTTH) در شهرهای بزرگ و چالش‌های پهنای باند بین‌الملل', 'ارزیابی وضعیت واقعی پوشش فیبر نوری و کیفیت دسترسی کاربران خانگی به اینترنت با پینگ پایین در سال جاری.', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('bleepingcomputer-zero-day-vpn-vulnerability-alert', 'هشدار امنیتی: رفع آسیب‌پذیری بحرانی در سرویس‌های VPN سازمانی و راهنمای به‌روزرسانی', 'محققان امنیتی نقص امنیتی مهمی را شناسایی کردند که به مهاجمان اجازه دور زدن احراز هویت اولیه را می‌داد.', '<p>یک گروه تحقیقاتی امنیت سایبری از کشف یک نقص روز-صفر (Zero-Day) در برخی نرم‌افزارهای تجاری خبر داد که با انتشار پچ‌های فوری برطرف شده است.</p><p>تیم فنی اتصال به تمام مدیران سیستم توصیه می‌کند نرم‌افزارهای خود را به جدیدترین نسخه هسته‌های منبع‌باز مثل Sing-Box و Xray-core ارتقا دهند.</p>', 'هشدار امنیتی: رفع آسیب‌پذیری بحرانی در سرویس‌های VPN سازمانی و راهنمای به‌روزرسانی', 'محققان امنیتی نقص امنیتی مهمی را شناسایی کردند که به مهاجمان اجازه دور زدن احراز هویت اولیه را می‌داد.', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
INSERT INTO public.news (slug, title, summary, content, meta_title, meta_description, image_url, is_published) VALUES ('open-source-ai-models-local-inference-privacy', 'رشد چشمگیر مدل‌های هوش مصنوعی منبع‌باز محلی و حفظ ۱۰۰٪ حریم خصوصی داده‌ها', 'چگونه اجرای مدل‌های زبانی روی سیستم‌های شخصی بدون ارسال داده به سرورهای خارجی، امنیت کاربران را متحول کرده است.', '<p>با پیشرفت فریم‌ورک‌های سبک مانند Ollama و llama.cpp، امکان اجرای دستیارهای هوش مصنوعی قدرتمند به صورت آفلاین و بدون نیاز به اینترنت فراهم شده است.</p><p>این رویکرد برای کاربرانی که به دلیل فیلترینگ یا حفظ حریم خصوصی مایل به ارسال اطلاعات به سرورهای خارجی نیستند، بهترین جایگزین محسوب می‌شود.</p>', 'رشد چشمگیر مدل‌های هوش مصنوعی منبع‌باز محلی و حفظ ۱۰۰٪ حریم خصوصی داده‌ها', 'چگونه اجرای مدل‌های زبانی روی سیستم‌های شخصی بدون ارسال داده به سرورهای خارجی، امنیت کاربران را متحول کرده است.', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&w=800&q=80', true) ON CONFLICT DO NOTHING;
